class Solution {
public:
    int numberOfSubstrings(string s) {
        int n = s.size();
        vector<int> zeros;
        for (int i = 0; i < n; i++) {
            if (s[i] == '0') zeros.push_back(i);
        }

        long long ans = 0;
        int maxZ = (int)sqrt((double)n) + 2;
        int z = (int)zeros.size();

        for (int l = 0; l < n; l++) {
            int idx = (int)(lower_bound(zeros.begin(), zeros.end(), l) - zeros.begin());

            for (int k = 0; k <= maxZ; k++) {
                int pos_k, pos_kp1;
                if (k == 0) {
                    pos_k = l - 1;
                } else {
                    if (idx + k - 1 >= z) break;
                    pos_k = zeros[idx + k - 1];
                }
                pos_kp1 = (idx + k >= z) ? n : zeros[idx + k];

                int leftBound = (k == 0) ? l : pos_k;
                int rightBound = pos_kp1 - 1;
                long long dominantLeft = (long long)l + (long long)k * k + k - 1;
                long long effectiveLeft = max((long long)leftBound, dominantLeft);
                long long count = (long long)rightBound - effectiveLeft + 1;
                if (count > 0) ans += count;
            }
        }

        return (int)ans;
    }
};
